<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Reporting{
 public static function init():void{add_action('admin_menu',[self::class,'menu'],12);}
 public static function menu():void{if(current_user_can('nvconsult_manage_applications'))add_submenu_page('edit.php?post_type=nv_application',__('Reports & KPIs','nvconsult-core'),__('Reports & KPIs','nvconsult-core'),'nvconsult_manage_applications','nvconsult-reports',[self::class,'render']);}
 public static function render():void{$apps=get_posts(['post_type'=>'nv_application','post_status'=>'private','numberposts'=>-1]);$total=count($apps);$approved=$rejected=$active=0;$types=[];$countries=[];foreach($apps as$a){$s=(string)get_post_meta($a->ID,'_nvconsult_status',true);if($s==='approved')$approved++;elseif($s==='rejected')$rejected++;elseif($s!=='closed')$active++;$t=(string)get_post_meta($a->ID,'_nvconsult_application_type',true)?:'other';$types[$t]=($types[$t]??0)+1;$c=(string)get_post_meta($a->ID,'_nvconsult_country',true);if($c)$countries[$c]=($countries[$c]??0)+1;}arsort($types);arsort($countries);$rate=$total?round(($approved/$total)*100,1):0;echo'<div class="wrap"><h1>'.esc_html__('NVConsult Reports & KPIs','nvconsult-core').'</h1><div style="display:grid;grid-template-columns:repeat(4,minmax(140px,1fr));gap:14px;max-width:900px;margin:20px 0">';foreach([[__('Applications','nvconsult-core'),$total],[__('Active','nvconsult-core'),$active],[__('Approved','nvconsult-core'),$approved],[__('Approval rate','nvconsult-core'),$rate.'%']]as$x)printf('<div style="background:#fff;border:1px solid #ddd;padding:18px;border-radius:10px"><strong style="font-size:28px;display:block">%s</strong>%s</div>',esc_html((string)$x[1]),esc_html($x[0]));echo'</div>';self::table(__('Applications by service','nvconsult-core'),$types);self::table(__('Top applicant countries','nvconsult-core'),array_slice($countries,0,15,true));echo'</div>';}
 private static function table(string$title,array$data):void{echo'<h2>'.esc_html($title).'</h2><table class="widefat striped" style="max-width:700px"><tbody>';if(!$data)echo'<tr><td>'.esc_html__('No data yet.','nvconsult-core').'</td></tr>';foreach($data as$k=>$v)printf('<tr><td>%s</td><td><strong>%d</strong></td></tr>',esc_html(ucwords(str_replace('_',' ',$k))),absint($v));echo'</tbody></table>';}
}
